#include "Story/HiramPoses.h"

namespace
{
	// The table itself, generated by Tools/dead_friend_poses.py (don't edit it by hand).
#include "Story/HiramPoseData.inl"
}

namespace HiramPoses
{
	const FDeadFriendPoseTable& Table()
	{
		static const FDeadFriendPoseTable Made{ GeneratedBones, GeneratedBoneCount, &GeneratedPoses[0][0], static_cast<int32>(EHiramPose::Count) };
		return Made;
	}

	FDeadFriendPose Make(EHiramPose Pose)
	{
		return DeadFriendPoses::FromTable(Table(), static_cast<int32>(Pose));
	}

	FDeadFriendPose AtTube(float TubeSide)
	{
		return Make(TubeSide >= 0.f ? EHiramPose::Tube : EHiramPose::TubeLeft);
	}

	const TCHAR* Name(EHiramPose Pose)
	{
		static const TCHAR* const Names[] = { TEXT("idle"), TEXT("tube"), TEXT("tube_left"), TEXT("talk") };
		static_assert(UE_ARRAY_COUNT(Names) == static_cast<int32>(EHiramPose::Count), "A name per pose");
		const int32 Index = static_cast<int32>(Pose);
		return Index >= 0 && Index < static_cast<int32>(EHiramPose::Count) ? Names[Index] : TEXT("?");
	}
}
